"""Frozen Wave5 supply snapshot DDL; independent of future ORM edits."""
# ruff: noqa: E501

TABLES = ('supply_source_captures', 'supply_snapshots', 'supply_current_snapshots', 'supply_kit_projections')

SCHEMA_SQL = (
    "\nCREATE TABLE supply_source_captures (\n\trevision INTEGER NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tcapture_key VARCHAR(160) NOT NULL, \n\trequest_sha256 VARCHAR(64) NOT NULL, \n\tsnapshot_id UUID NOT NULL, \n\texpires_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tinput_snapshot JSONB NOT NULL, \n\tbound_demand JSONB NOT NULL, \n\tproposed_snapshot JSONB NOT NULL, \n\tsources JSONB NOT NULL, \n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\treason TEXT NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (visibility IN ('private','product') AND build_revision > 0), \n\tUNIQUE (tenant_id, product_id, owner_id, capture_key), \n\tUNIQUE (tenant_id, product_id, snapshot_id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id, snapshot_id), \n\tCHECK (revision = 1 AND status = 'unapplied' AND expires_at > created_at)\n)\n\n",
    'CREATE INDEX ix_supply_source_captures_tenant_id ON supply_source_captures (tenant_id)',
    "\nCREATE TABLE supply_snapshots (\n\trevision INTEGER NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tcapture_id UUID NOT NULL, \n\tprevious_snapshot_id UUID, \n\tprevious_revision INTEGER, \n\tsnapshot JSONB NOT NULL, \n\tsnapshot_sha256 VARCHAR(64) NOT NULL, \n\tbound_demand JSONB NOT NULL, \n\treconciliation JSONB NOT NULL, \n\tsources JSONB NOT NULL, \n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\treason TEXT NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (visibility IN ('private','product') AND build_revision > 0), \n\tUNIQUE (tenant_id, product_id, build_id, revision), \n\tUNIQUE (tenant_id, product_id, build_id, id, revision), \n\tUNIQUE (tenant_id, product_id, capture_id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, capture_id, id) REFERENCES supply_source_captures (tenant_id, product_id, project_id, build_id, id, snapshot_id), \n\tFOREIGN KEY(tenant_id, product_id, build_id, previous_snapshot_id, previous_revision) REFERENCES supply_snapshots (tenant_id, product_id, build_id, id, revision), \n\tCHECK (status = 'recorded' AND revision > 0), \n\tCHECK ((previous_snapshot_id IS NULL AND previous_revision IS NULL AND revision = 1) OR (previous_snapshot_id IS NOT NULL AND previous_revision IS NOT NULL AND previous_snapshot_id <> id AND revision = previous_revision + 1))\n)\n\n",
    'CREATE INDEX ix_supply_snapshots_tenant_id ON supply_snapshots (tenant_id)',
    '\nCREATE TABLE supply_current_snapshots (\n\tproduct_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tsnapshot_id UUID NOT NULL, \n\tsnapshot_revision INTEGER NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, build_id), \n\tFOREIGN KEY(tenant_id, product_id, build_id, snapshot_id, snapshot_revision) REFERENCES supply_snapshots (tenant_id, product_id, build_id, id, revision), \n\tCHECK (snapshot_revision > 0)\n)\n\n',
    'CREATE INDEX ix_supply_current_snapshots_tenant_id ON supply_current_snapshots (tenant_id)',
    "\nCREATE TABLE supply_kit_projections (\n\trevision INTEGER NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tsupply_snapshot_id UUID NOT NULL, \n\tsupply_revision INTEGER NOT NULL, \n\tas_of TIMESTAMP WITH TIME ZONE NOT NULL, \n\tprojection JSONB NOT NULL, \n\tprojection_sha256 VARCHAR(64) NOT NULL, \n\tbound_demand JSONB NOT NULL, \n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\treason TEXT NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (visibility IN ('private','product') AND build_revision > 0), \n\tFOREIGN KEY(tenant_id, product_id, build_id, supply_snapshot_id, supply_revision) REFERENCES supply_snapshots (tenant_id, product_id, build_id, id, revision), \n\tCHECK (revision = 1 AND status = 'computed' AND supply_revision > 0), \n\tCHECK (as_of <= created_at)\n)\n\n",
    'CREATE INDEX ix_supply_kit_projections_tenant_id ON supply_kit_projections (tenant_id)',
)
